package com.dat.ai_receptionist_web.service.Catalog;
import com.dat.ai_receptionist_web.domain.Catalog.*; import com.dat.ai_receptionist_web.dto.*; import com.dat.ai_receptionist_web.dto.Catalog.*; import com.dat.ai_receptionist_web.error.*; import com.dat.ai_receptionist_web.error.code.CatalogErrorCode; import com.dat.ai_receptionist_web.mapper.Catalog.TrainingPlanRequirementMapper; import com.dat.ai_receptionist_web.repository.Catalog.*; import com.dat.ai_receptionist_web.repository.Training.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class TrainingPlanRequirementService {
 private final TrainingPlanRequirementRepository repository; private final TrainingPlanService plans; private final TrainingPlanRequirementMapper mapper; private final StudentEnrollmentScheduleRepository schedules; private final StudentSessionBookingRepository bookings;
 @Transactional(readOnly=true) public PageResponse<TrainingPlanRequirementDTO.SimpleResponse> list(UUID planId, Pageable pageable){return PageResponse.of(repository.findAllDetailed(planId,pageable),mapper::toSimpleResponse);} @Transactional(readOnly=true) public TrainingPlanRequirementDTO.Response get(UUID id){return mapper.toResponse(find(id));}
 @Transactional public TrainingPlanRequirementDTO.Response create(TrainingPlanRequirementDTO.CreateRequest r){var e=new TrainingPlanRequirement(); e.setTrainingPlan(plans.find(r.trainingPlanId())); mapper.updateEntity(r,e); return mapper.toResponse(repository.save(e));}
 @Transactional public TrainingPlanRequirementDTO.Response update(UUID id,TrainingPlanRequirementDTO.UpdateRequest r){var e=find(id); if(plans.sold(e.getTrainingPlan().getTrainingPlanId())) throw new ApiException(CatalogErrorCode.TRAINING_PLAN_CONFIGURATION_LOCKED); mapper.updateEntity(r,e); return mapper.toResponse(e);}
 @Transactional public void delete(UUID id){var e=find(id); if(schedules.existsByRequirement_TrainingPlanRequirementId(id)||bookings.existsByRequirement_TrainingPlanRequirementId(id))throw new ApiException(CatalogErrorCode.TRAINING_PLAN_IN_USE);repository.delete(e);} private TrainingPlanRequirement find(UUID id){return repository.findDetailedById(id).orElseThrow(()->new ApiException(CatalogErrorCode.TRAINING_PLAN_REQUIREMENT_NOT_FOUND));}
}
